```java
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class QuickSortTest {

    @Test
    public void testIntegerArray() {
        Integer[] array = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
        Integer[] expected = {1, 1, 2, 3, 3, 4, 5, 5, 5, 6, 9};
        QuickSort<Integer> quickSort = new QuickSort<>();
        quickSort.sort(array);
        assertArrayEquals(expected, array);
        System.out.println("Integer array number of comparisons: " + quickSort.getComparisonCount());
    }

    @Test
    public void testStringArray() {
        String[] array = {"banana", "apple", "cherry", "date", "elderberry", "fig", "grape"};
        String[] expected = {"apple", "banana", "cherry", "date", "elderberry", "fig", "grape"};
        QuickSort<String> quickSort = new QuickSort<>();
        quickSort.sort(array);
        assertArrayEquals(expected, array);
        System.out.println("String array number of comparisons: " + quickSort.getComparisonCount());
    }

    @Test
    public void testAlreadySortedArray() {
        Integer[] array = {1, 2, 3, 4, 5};
        Integer[] expected = {1, 2, 3, 4, 5};
        QuickSort<Integer> quickSort = new QuickSort<>();
        quickSort.sort(array);
        assertArrayEquals(expected, array);
        System.out.println("Already sorted array number of comparisons: " + quickSort.getComparisonCount());
    }

    @Test
    public void testReverseSortedArray() {
        Integer[] array = {5, 4, 3, 2, 1};
        Integer[] expected = {1, 2, 3, 4, 5};
        QuickSort<Integer> quickSort = new QuickSort<>();
        quickSort.sort(array);
        assertArrayEquals(expected, array);
        System.out.println("Reverse sorted array number of comparisons: " + quickSort.getComparisonCount());
    }

    @Test
